import { Router } from 'express'
import { mongoDBService } from '../services/mongodb.service.js'
import { gptService } from '../services/gpt.service.js'
import { audioProcessingService } from '../services/audio-processing.service.js'
import { responseValidationService } from '../services/response-validation.service.js'
import { ApiError } from '../types/index.js'
import { asyncHandler, validateUserId } from '../middleware/validation.middleware.js'
import { s3Service } from '../services/s3.service.js'

const router = Router()

/**
 * POST /interviews
 * Create a new interview session
 */
router.post('/', validateUserId, asyncHandler(async (req, res) => {
  const { type, duration_seconds, question_count } = req.body
  const userId = req.userId

  // Validate request
  if (!type || !duration_seconds || !question_count) {
    throw new ApiError({
      message: 'Missing required fields: type, duration_seconds, question_count',
      code: 'MISSING_REQUIRED_FIELDS',
      statusCode: 400
    })
  }

  if (!['behavioral', 'technical', 'psychometric'].includes(type)) {
    throw new ApiError({
      message: 'Invalid interview type',
      code: 'INVALID_INTERVIEW_TYPE',
      statusCode: 400
    })
  }

  // Generate interview ID
  const interviewId = `ivw_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`

  // Create interview session
  const session = {
    interview_id: interviewId,
    user_id: userId,
    type,
    question_count,
    duration_seconds,
    status: 'created',
    created_at: new Date().toISOString()
  }

  // Store session to MongoDB
  await mongoDBService.createInterviewSession(session)

  const response = {
    interview_id: interviewId,
    type,
    question_count,
    status: 'created',
    created_at: session.created_at
  }

  res.status(201).json(response)
}))

/**
 * GET /interviews/history
 * Get all interview sessions for the current user
 */
router.get('/history', validateUserId, asyncHandler(async (req, res) => {
  const userId = req.userId

  // Get all interview sessions for the user
  const sessions = await mongoDBService.getAllUserInterviewSessions(userId)

  // Format response with interview details
  const interviews = sessions.map(session => ({
    interview_id: session.interview_id,
    type: session.type,
    question_count: session.question_count || 0,
    duration_seconds: session.duration_seconds,
    status: session.status,
    created_at: session.created_at,
    completed_at: session.completed_at || null,
    // Get feedback score if available
    score: null // Will be populated from feedback if exists
  }))

  // Get feedback scores for completed interviews
  const completedInterviews = interviews.filter(i => i.status === 'completed')
  if (completedInterviews.length > 0) {
    const allFeedbacks = await mongoDBService.getAllUserInterviewFeedbacks(userId)
    
    // Filter feedbacks for our interview IDs and map scores
    interviews.forEach(interview => {
      if (interview.status === 'completed') {
        const feedback = allFeedbacks.find(f => f.interview_id === interview.interview_id)
        if (feedback && feedback.overall && feedback.overall.score) {
          interview.score = feedback.overall.score
        }
      }
    })
  }

  // Filter out interviews without scores (only show completed interviews with feedback)
  const scoredInterviews = interviews.filter(interview => 
    interview.status === 'completed' && interview.score !== null
  )

  // Sort by created_at descending (newest first)
  scoredInterviews.sort((a, b) => new Date(b.created_at) - new Date(a.created_at))

  res.status(200).json({
    interviews: scoredInterviews,
    total: scoredInterviews.length
  })
}))

/**
 * POST /interviews/:id/submit
 * Submit interview responses
 */
router.post('/:id/submit', validateUserId, asyncHandler(async (req, res) => {
  const { id: interviewId } = req.params
  const { responses } = req.body
  const userId = req.userId
  let failProcessCount = 0

  if (!responses || !Array.isArray(responses) || responses.length === 0) {
    throw new ApiError({
      message: 'Responses array is required',
      code: 'MISSING_RESPONSES',
      statusCode: 400
    })
  }

  // Get session from MongoDB
  const session = await mongoDBService.getInterviewSession(userId, interviewId)

  if (!session) {
    throw new ApiError({
      message: 'Interview session not found',
      code: 'SESSION_NOT_FOUND',
      statusCode: 404
    })
  }

  // Validate responses (unique questions and format)
  await responseValidationService.validateResponses(responses, interviewId, userId)

  // Process responses using the audio processing service
  const processedResponses = []

  for (const response of responses) {
    try {
      const processedResponse = await audioProcessingService.processResponse(
        response,
        userId,
        interviewId
      )
      processedResponses.push(processedResponse)
    } catch (error) {
      console.error(`Failed to process response for question ${response.question_id}:`, error)
        const errorResponse = {
          question_id: response.question_id,
          text: response.input_mode === 'voice' ? '' : '[Response processing failed]',
          transcript: response.input_mode === 'voice' ? '[Response processing failed]' : undefined,
          elapsed_seconds: response.elapsed_seconds || 0,
          input_mode: response.input_mode || 'text'
        }
        processedResponses.push(errorResponse)
        failProcessCount++
    }
  }
  
  // Store responses to MongoDB
  await mongoDBService.createInterviewResponses(interviewId, userId, processedResponses)

  // Update session status in MongoDB
  await mongoDBService.updateInterviewSession(userId, interviewId, {
    status: 'submitted'
  })

  const response = {
    interview_id: interviewId,
    status: 'submitted',
    received_count: processedResponses.length,
    fail_process_count: failProcessCount
  }

  res.status(200).json(response)
}))

/**
 * GET /interviews/:id/feedback
 * Get interview feedback (with polling support)
 */
router.get('/:id/feedback', validateUserId, asyncHandler(async (req, res) => {
  const { id: interviewId } = req.params
  const userId = req.userId

  // Check if feedback already exists in MongoDB
  const feedback = await mongoDBService.getInterviewFeedback(interviewId)

  // If feedback exists and is ready, return it
  if (feedback && feedback.status === 'ready') {
    return res.status(200).json({
      status: 'ready',
      items: feedback.items,
      overall: feedback.overall
    })
  }

  // If feedback is processing, return processing status
  if (feedback && feedback.status === 'processing') {
    return res.status(200).json({ status: 'processing' })
  }

  // If no feedback exists, start processing
  const session = await mongoDBService.getInterviewSession(userId, interviewId)

  if (!session) {
    throw new ApiError({
      message: 'Interview session not found',
      code: 'SESSION_NOT_FOUND',
      statusCode: 404
    })
  }

  const questions = await mongoDBService.getInterviewQuestions(interviewId)
  const responses = await mongoDBService.getInterviewResponses(interviewId)

  if (!questions || !responses || questions.length === 0 || responses.length === 0) {
    throw new ApiError({
      message: 'Interview data not found',
      code: 'INTERVIEW_DATA_NOT_FOUND',
      statusCode: 404
    })
  }

  // Create a processing status entry
  await mongoDBService.createOrUpdateInterviewFeedback({
    interview_id: interviewId,
    user_id: userId,
    status: 'processing',
    items: [],
    overall: { score: 0 }
  })

  // Generate feedback asynchronously (fire and forget)
  generateFeedbackAsync(interviewId, userId, questions, responses).catch((error) => {
    console.error(`Failed to generate feedback for interview ${interviewId}:`, error)
    // Optionally update status to 'failed' or keep as 'processing'
  })

  // Return processing status immediately
  res.status(200).json({ status: 'processing' })
}))

/**
 * GET /interviews/:id/questions/:questionId/audio
 * Provide a temporary signed URL to replay a voice response
 * Supports both questionId and questionIndex (for backward compatibility)
 */
router.get('/:id/questions/:questionId/audio', validateUserId, asyncHandler(async (req, res) => {
  const { id: interviewId, questionId } = req.params
  const userId = req.userId

  let responseDoc;

  // Try to find by question_id first
  responseDoc = await mongoDBService.getInterviewResponseByQuestion(interviewId, questionId, userId);

  // If not found and questionId looks like an index (number), try finding by index
  if (!responseDoc && !isNaN(questionId)) {
    const questionIndex = parseInt(questionId);
    responseDoc = await mongoDBService.getInterviewResponseByIndex(interviewId, questionIndex, userId);
  }

  if (!responseDoc) {
    throw new ApiError({
      message: 'Response not found for this question',
      code: 'RESPONSE_NOT_FOUND',
      statusCode: 404
    })
  }

  if (responseDoc.input_mode !== 'voice') {
    throw new ApiError({
      message: 'This response was text-only and has no audio to replay',
      code: 'RESPONSE_NOT_AUDIO',
      statusCode: 400
    })
  }

  // For testing/development, return a mock audio URL if S3 key is not available
  if (!responseDoc.audio_s3_key) {
    console.log('⚠️ No audio S3 key found, returning mock audio URL for testing');
    // Return a mock audio URL for testing purposes
    // In production, this should be a real signed URL
    res.status(200).json({
      interview_id: interviewId,
      question_id: responseDoc.question_id,
      response_id: responseDoc.response_id,
      audio_url:
        'data:audio/wav;base64,',
      expires_in: 300,
      mime_type: responseDoc.audio_mime_type || 'audio/wav',
      is_mock: true // Indicate this is mock data
    })
    return;
  }

  const expiresIn = 300
  const signedUrl = await s3Service.generateSignedUrl(
    responseDoc.audio_s3_key,
    'get',
    undefined,
    expiresIn
  )

  res.status(200).json({
    interview_id: interviewId,
    question_id: responseDoc.question_id, // Return the actual question_id
    response_id: responseDoc.response_id,
    audio_url: signedUrl,
    expires_in: expiresIn,
    mime_type: responseDoc.audio_mime_type || 'audio/webm'
  })
}))

/**
 * Generate feedback asynchronously
 */
async function generateFeedbackAsync(interviewId, userId, questions, responses) {
  try {
    // Generate feedback using GPT
    const feedbackItems = await gptService.generateFeedback(
      questions.map((q) => ({
        question_id: q.question_id,
        index: q.order,
        type: q.question_type,
        text: q.question_text,
        duration_seconds: 120
      })),
      responses.map((r) => {
        console.log(`🔍 Response for ${r.question_id}: input_mode=${r.input_mode}, text="${r.text?.substring(0, 50)}...", transcript="${r.transcript?.substring(0, 50)}..."`);
        return {
          question_id: r.question_id,
          text: r.text,
          elapsed_seconds: r.duration_seconds ?? 0,
          audio_s3_key: r.audio_s3_key,
          transcript: r.transcript,
          voice_analysis: r.voice_analysis, // Include voice analysis data
          input_mode: r.input_mode || 'text' // Include input mode
        };
      })
    )

    // Calculate overall score
    const overallScore = Math.round(
      (feedbackItems.reduce((sum, item) => sum + item.feedback.star.score, 0) /
        feedbackItems.length) *
        100
    )

    let summary = {
      strengths: [],
      needs_improvement: [],
      next_steps: ''
    }

    try {
      summary = await gptService.generateFeedbackSummary(feedbackItems)
    } catch (summaryError) {
      console.error(`Failed to generate interview summary for ${interviewId}:`, summaryError)
    }

    // Update feedback with ready status
    await mongoDBService.createOrUpdateInterviewFeedback({
      interview_id: interviewId,
      user_id: userId,
      status: 'ready',
      items: feedbackItems,
      overall: {
        score: overallScore,
        summary
      }
    })

    // Update session status in MongoDB
    await mongoDBService.updateInterviewSession(userId, interviewId, {
      status: 'completed',
      completed_at: new Date().toISOString()
    })

    console.log(`✅ Feedback generated successfully for interview ${interviewId}`)
  } catch (error) {
    console.error(`❌ Error generating feedback for interview ${interviewId}:`, error)
    throw error
  }
}

export default router
